using DSWI_T1_1.ViewModels;using Microsoft.AspNetCore.Mvc;namespace DSWI_T1_1.Controllers;public class CalculadoraController:Controller{[HttpGet]public IActionResult Index()=>View(new CalculadoraVm());[HttpPost,ValidateAntiForgeryToken]public IActionResult Prestamo(PrestamoVm m){if(!ModelState.IsValid)return View("Index",new CalculadoraVm{Prestamo=m});m.Cuotas=m.Monto>5000?3:m.Monto<1000?1:m.Monto>=2000&&m.Monto<=3000?2:5;m.Tasa=m.Monto<4000?.12m:.10m;m.Interes=Math.Round(m.Monto*m.Tasa.Value,2);m.Total=m.Monto+m.Interes;m.Cuota=Math.Round(m.Total.Value/m.Cuotas.Value,2);return View("Index",new CalculadoraVm{Prestamo=m});}[HttpPost,ValidateAntiForgeryToken]public IActionResult Envio(EnvioVm m){if(!ModelState.IsValid)return View("Index",new CalculadoraVm{Envio=m});m.Tarifa=m.Peso>50?2.50m:m.Peso<5?4m:m.Peso>=10&&m.Peso<=20?3m:3.50m;m.Subtotal=Math.Round(m.Peso*m.Tarifa.Value,2);m.Recargo=m.Internacional?15m:0m;m.Total=m.Subtotal+m.Recargo;return View("Index",new CalculadoraVm{Envio=m});}}